package com.fixmer.mared.technology.workspace.live122;
import com.fixmer.mared.Mared;import com.fixmer.genesis.technology.workspace.live122.*;import net.minecraft.server.MinecraftServer;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.level.storage.LevelResource;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.server.*;import net.neoforged.neoforge.network.PacketDistributor;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
/** Current player identity and Maop are captured/revalidated on the game thread; disk work is serialized. */
@EventBusSubscriber(modid=Mared.MOD_ID)
public final class WorkspaceServer122 {
 private WorkspaceServer122(){}private static final Map<MinecraftServer,Owner> owners=new IdentityHashMap<>();
 private static final class Rate{double tokens=8;long last=System.nanoTime();boolean take(){long now=System.nanoTime();tokens=Math.min(8,tokens+Math.max(0,now-last)*8.0/1e9);last=now;if(tokens<1)return false;tokens--;return true;}}
 private static final class Owner{final Path root;final ThreadPoolExecutor io=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(64),r->{var t=new Thread(r,"Genesis-workspace122");t.setDaemon(true);return t;});final Map<UUID,Rate> rates=new HashMap<>();final Set<UUID> pending=new HashSet<>();volatile boolean stopped;WorkspaceHub122 hub;Owner(Path root){this.root=root;}}
 @SubscribeEvent public static void start(ServerStartedEvent e){owners.put(e.getServer(),new Owner(e.getServer().getWorldPath(LevelResource.ROOT).resolve("genesis/workspaces122")));}
 private static boolean current(ServerPlayer p,MinecraftServer s){return p.getServer()==s&&s.getPlayerList().getPlayer(p.getUUID())==p;}
 private static void reply(ServerPlayer p,String id,Map<String,String> answer){try{var d=new TreeMap<>(answer);d.put("request",id);PacketDistributor.sendToPlayer(p,new WorkspacePayloads122.Response(WorkspaceCodec122.encode(d,WorkspaceCodec122.RESPONSE)));}catch(Exception e){Mared.LOGGER.warn("[Workspace122] Reply failed",e);}}
 public static void receive(ServerPlayer p,byte[] bytes){var s=p.getServer();if(s!=null)s.execute(()->accept(p,s,bytes));}
 private static void accept(ServerPlayer p,MinecraftServer s,byte[] bytes){if(!current(p,s)||!p.connection.hasChannel(WorkspacePayloads122.Response.TYPE.id()))return;Map<String,String> q;try{q=WorkspaceCodec122.decode(bytes,WorkspaceCodec122.REQUEST);WorkspaceHub122.request(q);}catch(Exception e){return;}String id=q.get("request");Owner o=owners.get(s);if(o==null||o.stopped){reply(p,id,Map.of("result","UNAVAILABLE"));return;}UUID actor=p.getUUID();if(o.rates.size()>1024)o.rates.clear();if(o.pending.contains(actor)||!o.rates.computeIfAbsent(actor,k->new Rate()).take()){reply(p,id,Map.of("result","BUSY"));return;}o.pending.add(actor);String label=p.getName().getString();boolean mayCreate=com.fixmer.mared.technology.permissions.MaopServer113.allowed(p,"WORKSPACE_CREATE");
  try{o.io.execute(()->{Map<String,String> result;try{var valid=new CompletableFuture<Boolean>();s.execute(()->valid.complete(!o.stopped&&owners.get(s)==o&&current(p,s)&&(!q.get("op").equals("CREATE")||com.fixmer.mared.technology.permissions.MaopServer113.allowed(p,"WORKSPACE_CREATE"))));if(!valid.get(3,TimeUnit.SECONDS))throw new SecurityException("DENIED");if(o.hub==null)o.hub=new WorkspaceHub122(o.root);if(q.get("op").equals("IMPORT")){UUID legacy=UUID.fromString(q.get("project"));o.hub.checkImport(actor,legacy);result=o.hub.importLegacy(actor,com.fixmer.mared.technology.workspace.WorkspaceServer112.freeze122(p,s,legacy).get(8,TimeUnit.SECONDS));}else result=o.hub.execute(actor,mayCreate,label,q);}catch(Exception e){while((e instanceof ExecutionException||e instanceof CompletionException)&&e.getCause() instanceof Exception cause)e=cause;String code=e.getMessage();if(e instanceof SecurityException)code="DENIED";else if(e instanceof IllegalArgumentException)code="INVALID";else if(code==null||!Set.of("CONFLICT","LIMIT","TEXT_LIMIT","DOCUMENT_LIMIT","LEASE","MISSING","NOT_TEXT","EXISTS_OR_LIMIT","REVIEW_REQUIRED","STALE_RELEASE","STALE_APPROVAL","NOT_APPROVED","DENIED","DELETE_REVIEW_REQUIRED","REQUEST_REUSED").contains(code)){Mared.LOGGER.warn("[Workspace122] {} failed",q.get("op"),e);code="IO_ERROR";}result=Map.of("result",code);}Map<String,String> answer=result;s.execute(()->{o.pending.remove(actor);if(!o.stopped&&owners.get(s)==o&&current(p,s)){var d=new TreeMap<>(answer);if(d.containsKey("members")){var online=new StringBuilder();for(ServerPlayer peer:s.getPlayerList().getPlayers()){String name=peer.getName().getString();if(name.matches("[A-Za-z0-9_]{1,16}"))online.append(peer.getUUID()).append('|').append(name).append('\n');if(online.length()>4000)break;}d.put("online",online.toString());}reply(p,id,d);}});});}catch(RejectedExecutionException e){o.pending.remove(actor);reply(p,id,Map.of("result","BUSY"));}
 }
 @SubscribeEvent public static void stop(ServerStoppedEvent e){Owner o=owners.remove(e.getServer());if(o==null)return;o.stopped=true;o.io.getQueue().clear();try{o.io.execute(()->{if(o.hub!=null)try{o.hub.close();}catch(Exception ex){Mared.LOGGER.warn("[Workspace122] Close failed",ex);}});}finally{o.io.shutdown();}}
}
